import sys
data = sys.stdin.read().split()
if data:
    num, den = int(data[0]), int(data[1])
    if num == 0: print('0'); sys.exit(0)
    res = []
    if (num < 0) ^ (den < 0): res.append('-')
    num, den = abs(num), abs(den)
    res.append(str(num // den))
    rem = num % den
    if rem == 0: print(''.join(res)); sys.exit(0)
    res.append('.')
    seen = {}
    while rem != 0:
        if rem in seen:
            res.insert(seen[rem], '(')
            res.append(')')
            break
        seen[rem] = len(res)
        rem *= 10
        res.append(str(rem // den))
        rem %= den
    print(''.join(res))
